-- Synthetic fixture schema only; run with the disposable test harness, never production.
\set ON_ERROR_STOP on
begin;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
do $$
declare co uuid:=gen_random_uuid(); other_co uuid:=gen_random_uuid(); u uuid:=gen_random_uuid(); other_u uuid:=gen_random_uuid(); customer uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); s1 uuid;s2 uuid;d staff_notification_deliveries;devices jsonb;
begin
 insert into companies values(co),(other_co);insert into profiles(id) values(u),(other_u),(customer);
 insert into company_members(company_id,profile_id,member_role) values(co,u,'dispatcher'),(other_co,other_u,'owner');
 insert into communication_conversations(id,company_id) values(c,co);
 perform set_config('request.jwt.claim.sub',u::text,true);
 execute 'set local role authenticated';
 s1:=save_staff_push_subscription(co,'https://web.push.apple.com/test-1',repeat('A',87),repeat('A',22),array['inbound_sms']);
 s2:=save_staff_push_subscription(co,'https://fcm.googleapis.com/test-2',repeat('A',87),repeat('A',22),array['inbound_sms']);
 perform pg_temp.ok(jsonb_array_length(staff_push_settings(co)->'devices')=2,'multiple owned devices');
 perform pg_temp.ok(save_staff_push_subscription(co,'https://web.push.apple.com/test-1',repeat('A',87),repeat('A',22),array['inbound_sms'])=s1,'resubscribe same endpoint idempotent');
 begin perform save_staff_push_subscription(other_co,'https://web.push.apple.com/test-x',repeat('A',87),repeat('A',22),array['inbound_sms']);raise exception 'cross company accepted';exception when insufficient_privilege then raise notice 'PASS cross-company subscription denied';end;
 begin perform save_staff_push_subscription(co,'http://127.0.0.1/internal',repeat('A',87),repeat('A',22),array['inbound_sms']);raise exception 'bad URL accepted';exception when check_violation then raise notice 'PASS unsafe endpoint denied in SQL';end;
 begin perform prepare_staff_push_devices(gen_random_uuid(),gen_random_uuid());raise exception 'client worker accepted';exception when insufficient_privilege then raise notice 'PASS client cannot access worker RPC';end;
 begin perform 1 from staff_push_subscriptions;raise exception 'client enumerated keys';exception when insufficient_privilege then raise notice 'PASS direct subscription key access denied';end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',other_u::text,true);execute 'set local role authenticated';
 begin perform save_staff_push_subscription(other_co,'https://web.push.apple.com/test-1',repeat('A',87),repeat('A',22),array['inbound_sms']);raise exception 'endpoint stolen';exception when insufficient_privilege then raise notice 'PASS endpoint cannot transfer across users';end;
 begin perform staff_push_settings(co);raise exception 'foreign settings read';exception when insufficient_privilege then raise notice 'PASS foreign settings denied';end;
 execute 'reset role';perform set_config('request.jwt.claim.sub',customer::text,true);execute 'set local role authenticated';
 begin perform save_staff_push_subscription(co,'https://web.push.apple.com/customer',repeat('A',87),repeat('A',22),array['inbound_sms']);raise exception 'customer accepted';exception when insufficient_privilege then raise notice 'PASS non-staff customer denied';end;
 execute 'reset role';
 insert into communication_messages values(gen_random_uuid(),c,'sms','inbound','customer');
 execute 'set local role service_role';select * into d from claim_staff_notification_deliveries(array['push'],1);
 devices:=prepare_staff_push_devices(d.id,d.lease_token);
 perform pg_temp.ok(jsonb_array_length(devices)=2,'canonical queue fans out to owned devices');
 perform pg_temp.ok(not reserve_staff_push_device(d.id,gen_random_uuid(),s1),'wrong lease denied');
 perform pg_temp.ok(reserve_staff_push_device(d.id,d.lease_token,s1),'first device reservation');
 perform pg_temp.ok(not reserve_staff_push_device(d.id,d.lease_token,s1),'duplicate device reservation rejected');
 perform pg_temp.ok(finish_staff_push_device(d.id,d.lease_token,s1,'accepted',201),'device acceptance persisted');
 perform pg_temp.ok(reserve_staff_push_device(d.id,d.lease_token,s2),'second device independent');
 perform finish_staff_push_device(d.id,d.lease_token,s2,'retryable',429);
 perform finish_staff_notification_delivery(d.id,d.lease_token,'retryable',null,'429','rate_limit');
 execute 'reset role';update staff_notification_deliveries set next_attempt_at=clock_timestamp()-interval '1 second' where id=d.id;
 execute 'set local role service_role';select * into d from claim_staff_notification_deliveries(array['push'],1);
 perform prepare_staff_push_devices(d.id,d.lease_token);
 perform pg_temp.ok(not reserve_staff_push_device(d.id,d.lease_token,s1),'accepted device never resent on parent retry');
 perform pg_temp.ok(reserve_staff_push_device(d.id,d.lease_token,s2),'rejected device retry allowed');
 perform finish_staff_push_device(d.id,d.lease_token,s2,'permanent',410);
 execute 'reset role';perform pg_temp.ok((select status='expired' from staff_push_subscriptions where id=s2),'expired endpoint removed from active set');
 perform set_config('request.jwt.claim.sub',u::text,true);execute 'set local role authenticated';
 perform pg_temp.ok(jsonb_array_length(staff_push_settings(co)->'devices')=1,'expired device hidden from active settings');
 perform revoke_staff_push_subscription(co,'https://web.push.apple.com/test-1');
 perform pg_temp.ok(jsonb_array_length(staff_push_settings(co)->'devices')=0,'unsubscribe revokes own device');
 perform pg_temp.ok(jsonb_array_length(staff_push_settings(co)->'events')=0,'last unsubscribe disables Push opt-in');
 execute 'reset role';
 perform pg_temp.ok(not exists(select 1 from staff_notification_preferences where telegram_enabled or sms_enabled),'no Telegram or SMS enabled');
 -- Revocation between queue claim and device reservation is enforced again.
 perform set_config('request.jwt.claim.sub',u::text,true);execute 'set local role authenticated';
 s1:=save_staff_push_subscription(co,'https://web.push.apple.com/test-3',repeat('A',87),repeat('A',22),array['inbound_sms']);
 execute 'reset role';insert into communication_messages values(gen_random_uuid(),c,'sms','inbound','customer');
 execute 'set local role service_role';select * into d from claim_staff_notification_deliveries(array['push'],1);perform prepare_staff_push_devices(d.id,d.lease_token);execute 'reset role';
 update company_members set member_status='suspended',suspended_at=clock_timestamp() where profile_id=u;
 execute 'set local role service_role';perform pg_temp.ok(not reserve_staff_push_device(d.id,d.lease_token,s1),'revoked staff cannot dispatch');execute 'reset role';
 update company_members set member_status='active',suspended_at=null where profile_id=u;
 update staff_notification_preferences set quiet_start='00:00',quiet_end='00:00' where recipient_profile_id=u;
 execute 'set local role service_role';perform pg_temp.ok(not reserve_staff_push_device(d.id,d.lease_token,s1),'quiet hours rechecked before device send');execute 'reset role';
 update staff_notification_preferences set quiet_start=null,quiet_end=null,push_enabled=false where recipient_profile_id=u;
 execute 'set local role service_role';perform pg_temp.ok(not reserve_staff_push_device(d.id,d.lease_token,s1),'opt-out rechecked before device send');execute 'reset role';
 perform set_config('request.jwt.claim.sub',u::text,true);execute 'set local role authenticated';
 perform revoke_staff_push_subscription(co,'https://web.push.apple.com/test-3');
 perform save_staff_push_subscription(co,'https://web.push.apple.com/test-3',repeat('A',87),repeat('A',22),array['inbound_sms']);
 execute 'reset role';execute 'set local role service_role';
 perform pg_temp.ok(jsonb_array_length(prepare_staff_push_devices(d.id,d.lease_token))=0,'reactivated device cannot receive earlier events');
 perform pg_temp.ok(not reserve_staff_push_device(d.id,d.lease_token,s1),'old device work cannot bypass reactivation cutoff');
 execute 'reset role';
 perform pg_temp.ok((select count(*)=2 from communication_messages where conversation_id=c),'no duplicate business events');
 perform pg_temp.ok(not exists(select 1 from communication_messages where direction='outbound'),'no customer messages');
end$$;
rollback;
